function addRangeChart(pptx,ranked,payload){competencyGroups(ranked).forEach((page,pageIndex)=>{const slide=pptx.addSlide();contentChrome(slide,competencyGroups(ranked).length>1?`Distribuția rezultatelor – pe competențe (mediană) · ${pageIndex+1}/${competencyGroups(ranked).length}`:"Distribuția rezultatelor – pe competențe (mediană)");const low=payload.bands.low,high=payload.bands.high,chartY=1.02,chartH=5.48;slide.addShape(window.__bhbPptx.ShapeType.rect,{x:.78,y:chartY+(5-high)/4*chartH,w:8.92,h:(high-low)/4*chartH,fill:{color:C.grey,transparency:72},line:{color:C.grey,transparency:100}});slide.addChart(window.__bhbPptx.ChartType.line,[{name:"Cel mai mic scor",labels:page.map(item=>item.competency),values:page.map(item=>item.min)},{name:"Cel mai mare scor",labels:page.map(item=>item.competency),values:page.map(item=>item.max)},{name:"Mediana sau scorul median",labels:page.map(item=>item.competency),values:page.map(item=>item.median)}],{x:.78,y:chartY,w:8.92,h:chartH,...chartOptions(),showLegend:false,chartColors:[C.range,C.range,C.range],lineSize:0,lineDataSymbol:"circle",lineDataSymbolSize:30});image(slide,window.__bhbRangeLegendData,10.12,1.2,2.45,3.83);addSources(slide,"Template - raport de grup - RO.pptx · slide 4 (native stock chart and tightly cropped PII-free legend reference)");});}
function addRanking(pptx,ranked,colors){competencyGroups(ranked).forEach((page,pageIndex)=>{const slide=pptx.addSlide();contentChrome(slide,competencyGroups(ranked).length>1?`Distribuția rezultatelor – media pe competențe · ${pageIndex+1}/${competencyGroups(ranked).length}`:"Distribuția rezultatelor – media pe competențe");slide.addChart(window.__bhbPptx.ChartType.bar,page.map(item=>({name:item.competency,labels:[item.competency],values:[Number(item.mean.toFixed(2))]})),{x:1.05,y:1,w:10.5,h:5.55,...chartOptions(),barDir:"bar",showLegend:true,legendPos:"b",legendFontFace:FONT_BODY,legendFontSize:11,catAxisHidden:true,chartColors:page.map(item=>colors.get(item.competency)),catAxisLabelFontSize:10,dataLabelFontFace:FONT_BODY,dataLabelFontSize:20,dataLabelFontBold:true,dataLabelColor:C.white,dataLabelPosition:"inEnd"});addSources(slide,"Template - raport de grup - RO.pptx · slide 5 (competency-average ranking; stable competency colors)");});}
function addBenchmarkSummary(pptx,payload){const scores=payload.records.map(record=>({name:record.name,score:Object.values(record.scores).filter(Number.isFinite).reduce((sum,value,_index,values)=>sum+value/values.length,0)})).sort((a,b)=>b.score-a.score),b=payload.bands,perPage=12;for(let start=0;start<scores.length;start+=perPage){const page=scores.slice(start,start+perPage),slide=pptx.addSlide();contentChrome(slide,"Distribuția pe media competențelor");slide.addTable([[{text:"Media",options:{bold:true,color:C.white,fill:C.navy,align:"center"}},{text:"Participant",options:{bold:true,color:C.white,fill:C.navy,align:"left"}}],...page.map(item=>[{text:fixed(item.score),options:{align:"center",color:C.navy}},{text:item.name,options:{color:C.navy}}])],{x:.9,y:1.1,w:4.3,h:5.4,fontFace:FONT_BODY,fontSize:9,margin:.04,border:{type:"solid",color:"E3D38C",pt:.75},colW:[1.1,3.2],rowH:.34,fill:C.white,autoPage:false});slide.addText(`Rezultate raportate la benchmark (${b.low}-${b.high})`,{x:6,y:1.25,w:5.3,h:.28,fontFace:FONT_HEAD,fontSize:14,bold:true,color:C.navy,margin:0});slide.addText([`${percent(b.above,b.n)} au obținut o medie generală peste ${b.high}`,`${percent(b.typical,b.n)} au obținut o medie generală între ${b.low} – ${b.high}`,`${percent(b.below,b.n)} au obținut o medie generală mai mică de ${b.low}`].map(item=>`• ${item}`).join("\n"),{x:6,y:2,w:5.2,h:2.2,fontFace:FONT_BODY,fontSize:12,color:C.navy,margin:0,breakLine:false});if(scores.length>perPage)slide.addText(`${start+1}–${Math.min(start+perPage,scores.length)} din ${scores.length}`,{x:3.4,y:6.58,w:1.7,h:.16,fontFace:FONT_BODY,fontSize:7,color:C.grey,align:"right",margin:0});addSources(slide,"Template - raport de grup - RO.pptx · slide 7 (native table and source-defined benchmark summary; appendix)");}}
function addBenchmark(pptx,payload){const slide=pptx.addSlide(),b=payload.bands,shares={below:b.n?b.below/b.n:0,typical:b.n?b.typical/b.n:0,above:b.n?b.above/b.n:0};contentChrome(slide,"Distribuția pe media competențelor – toată populația");slide.addChart(window.__bhbPptx.ChartType.bar,[{name:`Mai mică de ${b.low}`,labels:["Participanți"],values:[shares.below]},{name:`Între ${b.low} – ${b.high}`,labels:["Participanți"],values:[shares.typical]},{name:`Peste ${b.high}`,labels:["Participanți"],values:[shares.above]}],{x:.85,y:1.45,w:7.9,h:3.6,barDir:"bar",barGrouping:"percentStacked",dataLabelPosition:"ctr",dataLabelFontFace:FONT_BODY,dataLabelFontSize:18,dataLabelFontBold:true,dataLabelColor:C.white,dataLabelFormatCode:"0%",catAxisLabelFontFace:FONT_BODY,catAxisLabelFontSize:11,valAxisLabelFontFace:FONT_BODY,valAxisLabelFontSize:9,valAxisLabelFormatCode:"0%",showLegend:true,legendPos:"b",showValue:true,chartColors:[C.navy,C.grey,C.yellow],valAxisMinVal:0,valAxisMaxVal:1,valAxisMajorUnit:.25});slide.addText([`${percent(b.typical,b.n)} au obținut o medie generală între ${b.low} – ${b.high}`,`${percent(b.above,b.n)} au obținut o medie generală peste ${b.high}`,`${percent(b.below,b.n)} au obținut o medie generală mai mică de ${b.low}`].map(item=>`• ${item}`).join("\n"),{x:9.05,y:1.7,w:3,h:2.05,fontFace:FONT_BODY,fontSize:11.5,color:C.navy,margin:0,breakLine:false});slide.addText(`Benchmark pe baza evaluărilor Trend: între ${b.low} și ${b.high} – performanță la nivel mediu.`,{x:1,y:6.2,w:10.8,h:.25,fontFace:FONT_BODY,fontSize:10,color:C.navy,margin:0});addSources(slide,"Template - raport de grup - RO.pptx · slides 7–8 (source-defined benchmark distribution)");}
function addParticipantComparison(pptx,payload,ranked,colors){const ordered=payload.records.slice().sort((a,b)=>overall(b)-overall(a)),perPage=participantComparisonPageSize;for(let start=0;start<ordered.length;start+=perPage){const records=ordered.slice(start,start+perPage),slide=pptx.addSlide();contentChrome(slide,"Rezultate pe competențe / participant");slide.addChart(window.__bhbPptx.ChartType.bar,ranked.map(item=>({name:item.competency,labels:records.map(r=>r.name),values:records.map(r=>r.scores[item.competency])})),{x:.9,y:1.15,w:11.55,h:5.2,...chartOptions(),barDir:"col",showLegend:true,legendPos:"b",showValue:false,chartColors:ranked.map(item=>colors.get(item.competency)),catAxisLabelFontSize:8,legendFontSize:12});if(ordered.length>perPage)slide.addText(`${start+1}–${Math.min(start+perPage,ordered.length)} din ${ordered.length}`,{x:11.15,y:6.62,w:1.1,h:.14,fontFace:FONT_BODY,fontSize:6.5,color:C.grey,align:"right",margin:0});addSources(slide,"Template - raport de grup - RO.pptx · slide 9 (participant comparison; appendix)");}}
function addCompetencyDistribution(pptx,payload,ranked,colors){for(const item of ranked){const scored=payload.records.filter(record=>Number.isFinite(record.scores[item.competency])).sort((a,b)=>b.scores[item.competency]-a.scores[item.competency]),perPage=participantChartPageSize(scored);for(let start=0;start<scored.length;start+=perPage){const records=scored.slice(start,start+perPage),slide=pptx.addSlide();contentChrome(slide,"Distribuția pe competențe",window.__bhbObservationsBackgroundData||window.__bhbReportBackgroundData);slide.addText(item.competency,{x:.9,y:.7,w:9.7,h:.24,fontFace:FONT_HEAD,fontSize:14,bold:true,color:C.navy,margin:0,breakLine:false});slide.addChart(window.__bhbPptx.ChartType.bar,[{name:item.competency,labels:records.map(record=>record.name),values:records.map(record=>record.scores[item.competency])}],{x:.9,y:1.05,w:11.55,h:5.12,...chartOptions(),showLegend:false,showValue:true,chartColors:[colors.get(item.competency)],catAxisLabelFontSize:8,valAxisMinVal:1,valAxisMaxVal:5,valAxisMajorUnit:.5});slide.addText(`n = ${item.n} · mediană ${fixed(item.median)} · minim ${fixed(item.min)} · maxim ${fixed(item.max)}`,{x:.9,y:6.27,w:10.2,h:.2,fontFace:FONT_BODY,fontSize:9,color:C.navy,align:"center",margin:0});if(scored.length>perPage)slide.addText(`${start+1}–${Math.min(start+perPage,scored.length)} din ${scored.length}`,{x:11.25,y:6.28,w:1.1,h:.16,fontFace:FONT_BODY,fontSize:7,color:C.grey,align:"right",margin:0});addSources(slide,"Template - raport de grup - RO.pptx · slide 13 (native participant-level distribution per competency; appendix)");}}}
function addBehaviorProfiles(pptx,behaviors){const addColumn=(slide,items,{x,heading})=>{slide.addText(heading,{x,y:1.25,w:5.5,h:.3,fontFace:FONT_HEAD,fontSize:14,bold:true,color:C.white,margin:0,breakLine:false});items.forEach((item,index)=>{const y=1.72+index*1.42,copy=item.score2||item.score0||item.behavior;slide.addText(String(index+1),{x,y,w:.28,h:.24,fontFace:FONT_HEAD,fontSize:14,bold:true,color:C.white,align:"center",margin:0});slide.addText(copy,{x:x+.4,y,w:4.8,h:.92,fontFace:FONT_BODY,fontSize:12,color:C.white,margin:0,breakLine:false});});};behaviorInsights(behaviors).forEach(insight=>{const slide=pptx.addSlide();contentChrome(slide,"Comportamente cheie",window.__bhbBehaviorBackgroundData||window.__bhbReportBackgroundData,{dark:true});slide.addText(insight.competency,{x:.8,y:.65,w:9.8,h:.22,fontFace:FONT_HEAD,fontSize:14,bold:true,color:C.white,margin:0,breakLine:false});slide.addText("Comportamentele sintetizează punctele forte și prioritățile de dezvoltare ale grupului.",{x:.8,y:.94,w:8,h:.18,fontFace:FONT_BODY,fontSize:10.5,color:C.white,margin:0});addColumn(slide,insight.strengths,{x:.8,heading:"Comportamente care susțin performanța"});addColumn(slide,insight.development,{x:6.9,heading:"Arii prioritare de dezvoltare"});addSources(slide,"Template - raport de grup - RO.pptx · behavior layout; behavior insight selection from detailed export; full inventory remains in audit XLSX");});}
function addConclusions(pptx,metadata){if(!safeText(metadata.conclusions))return;const slide=pptx.addSlide();contentChrome(slide,"Concluzii și recomandări");slide.addText(metadata.conclusions,{x:1.1,y:1.35,w:10.9,h:4.7,fontFace:FONT_BODY,fontSize:16,color:C.navy,margin:.1,breakLine:false});addSources(slide,"Template - raport de grup - RO.pptx · slides 20–21 (layout only; copy supplied explicitly by the user)");}
function addBhbReport(pptx,payload,scope){const ranked=payload.calculations.filter(item=>item.mean!==null).slice().sort((a,b)=>b.mean-a.mean),colors=competencyColors(ranked),main=scope!=="appendix",appendix=scope!=="main";if(main){pptx.addSection({title:"Raport principal"});addCover(pptx,payload.metadata);addMethodology(pptx,payload);addExecutiveSummary(pptx,payload);if(sectionEnabled(payload,"distribution")){addSectionIntro(pptx,"Distribuția rezultatelor","distribution");addRangeChart(pptx,ranked,payload);addRanking(pptx,ranked,colors);}if(sectionEnabled(payload,"benchmark"))addBenchmark(pptx,payload);if(sectionEnabled(payload,"keyFindings")){addSectionIntro(pptx,"Analiza observațiilor","observations");if(payload.metadata.includeCompetencySummary)addCompetencySummary(pptx,ranked);addKeyFindings(pptx,payload,ranked);}if(sectionEnabled(payload,"behavior")&&payload.behaviorAggregates.length){pptx.addSection({title:"Profil comportamental"});addSectionIntro(pptx,"Profil comportamental","behavior");addBehaviorProfiles(pptx,payload.behaviorAggregates);}if(sectionEnabled(payload,"conclusions"))addConclusions(pptx,payload.metadata);}if(appendix&&(sectionEnabled(payload,"appendixBenchmark")||sectionEnabled(payload,"appendixComparison")||sectionEnabled(payload,"appendixDistribution"))){pptx.addSection({title:"Anexă"});addAppendixDivider(pptx);if(sectionEnabled(payload,"appendixBenchmark"))addBenchmarkSummary(pptx,payload);if(sectionEnabled(payload,"appendixComparison"))addParticipantComparison(pptx,payload,ranked,colors);if(sectionEnabled(payload,"appendixDistribution"))addCompetencyDistribution(pptx,payload,ranked,colors);}addClosing(pptx);}
function addCompetencySummary(pptx,ranked){const split=Math.ceil(ranked.length/2),slide=pptx.addSlide(),high=ranked.slice(0,split),low=ranked.slice(split).reverse();contentChrome(slide,"Puncte forte și recomandări de grup");slide.addTable([[{text:"Abilități cheie – Puncte forte",options:{bold:true,color:C.white,fill:C.navy,align:"center"}},{text:"Arii de dezvoltare",options:{bold:true,color:C.white,fill:C.aqua,align:"center"}}],...Array.from({length:Math.max(high.length,low.length)},(_,index)=>[{text:high[index]?`${high[index].competency} (${fixed(high[index].mean)})`:"",options:{color:C.navy,bold:!!high[index]}},{text:low[index]?`${low[index].competency} (${fixed(low[index].mean)})`:"",options:{color:C.navy,bold:!!low[index]}}])],{x:1.05,y:1.35,w:11.1,h:3.5,fontFace:FONT_BODY,fontSize:14,margin:.12,border:{type:"solid",color:"E3D38C",pt:.75},colW:[5.55,5.55],rowH:.65,fill:C.white});addSources(slide,"Legacy optional competency summary; Key Findings slides are now generated for every competency.");}
