function trendCover(pptx,metadata){const slide=pptx.addSlide();image(slide,imageData("trend-cover-frame-asset"));slide.addShape(window.__grfPptx.ShapeType.rect,{x:7.08,y:2.78,w:5.0,h:1.85,fill:{color:T.navy},line:{color:T.navy}});slide.addShape(window.__grfPptx.ShapeType.rect,{x:7.08,y:4.63,w:3.05,h:.4,fill:{color:T.yellow},line:{color:T.yellow}});slide.addText("CONFIDENȚIAL",{x:8.2,y:1.35,w:2.2,h:.24,fontFace:FONT_HEAD,fontSize:11,bold:true,color:T.navy,margin:0});slide.addText([metadata.projectName||metadata.clientName,metadata.clientName&&metadata.clientName!==metadata.projectName?`Client: ${metadata.clientName}`:""].filter(Boolean).join("\n"),{x:7.4,y:3.12,w:4.35,h:.85,fontFace:FONT_BODY,fontSize:22,color:T.white,margin:.05,breakLine:false});slide.addText([metadata.context||"Raport de grup",metadata.reportDate].filter(Boolean).join(" · "),{x:7.4,y:4.7,w:4.2,h:.2,fontFace:FONT_BODY,fontSize:11,bold:true,color:T.white,margin:0});addSources(slide,"Template - raport de grup - RO.pptx · slide 1 (TREND cover frame); client/project copy supplied at generation time");}
function trendMethodology(pptx,payload){methodologyPages(payload).forEach((page,index)=>{const slide=pptx.addSlide();trendFrame(slide,"trend-methodology-frame-asset",index?"PRIVIRE DE ANSAMBLU ASUPRA PROIECTULUI · METODOLOGIE (CONTINUARE)":"PRIVIRE DE ANSAMBLU ASUPRA PROIECTULUI · METODOLOGIE");[page.left,page.right].forEach((items,column)=>items.forEach((item,itemIndex)=>slide.addText(itemIndex===0?item:`• ${item}`,{x:column?6.75:1.0,y:1.05+itemIndex*.48,w:5.15,h:itemIndex===0?.25:.38,fontFace:itemIndex===0?FONT_HEAD:FONT_BODY,fontSize:itemIndex===0?10.5:9.5,bold:itemIndex===0,color:T.navy,margin:0,breakLine:false})));addSources(slide,"Template - raport de grup - RO.pptx · slide 2 (TREND methodology frame)");});}
function trendExecutive(pptx,payload){const summary=executiveSummary(payload),slide=pptx.addSlide();trendFrame(slide,"trend-benchmark-summary-frame-asset","Executive Summary");slide.addText(`${summary.population}`,{x:1.0,y:1.2,w:1.7,h:.55,fontFace:FONT_HEAD,fontSize:30,bold:true,color:T.navy,margin:0});slide.addText("participanți evaluați",{x:1.0,y:1.82,w:2.8,h:.22,fontFace:FONT_BODY,fontSize:11,color:T.navy,margin:0});slide.addText(`${summary.distribution[1]?.value||0}%`,{x:4.15,y:1.2,w:1.7,h:.55,fontFace:FONT_HEAD,fontSize:30,bold:true,color:T.aqua,margin:0});slide.addText("în intervalul benchmark",{x:4.15,y:1.82,w:2.8,h:.22,fontFace:FONT_BODY,fontSize:11,color:T.navy,margin:0});slide.addText(`Cel mai bine reprezentată: ${summary.strongest?.competency||"—"}\nPrincipală oportunitate: ${summary.weakest?.competency||"—"}`,{x:1.0,y:2.5,w:5.0,h:.85,fontFace:FONT_BODY,fontSize:14,bold:true,color:T.navy,margin:0,breakLine:false});slide.addText(summary.distribution.map(item=>`• ${item.value}% ${item.label.toLowerCase()}`).join("\n"),{x:7.0,y:1.35,w:4.4,h:1.1,fontFace:FONT_BODY,fontSize:11,color:T.navy,margin:0,breakLine:false});const copy=[summary.strengths.length?`Comportamente evidențiate: ${summary.strengths.map(item=>item.score2||item.behavior).join("; ")}`:"",summary.development.length?`Priorități comportamentale: ${summary.development.map(item=>item.score0||item.behavior).join("; ")}`:""].filter(Boolean).join("\n\n");if(copy)slide.addText(copy,{x:1.0,y:3.75,w:10.6,h:1.9,fontFace:FONT_BODY,fontSize:11,color:T.navy,margin:0,breakLine:false});addSources(slide,"Feedback raport.docx · Executive Summary requirements; TREND template family");}
function trendRange(pptx,ranked,payload){const groups=competencyGroups(ranked);groups.forEach((page,index)=>{const slide=pptx.addSlide();trendFrame(slide,"trend-range-frame-asset",`Distribuția rezultatelor – pe competențe (mediană)${groups.length>1?` · ${index+1}/${groups.length}`:""}`);slide.addChart(window.__grfPptx.ChartType.line,[{name:"Cel mai mic scor",labels:page.map(item=>item.competency),values:page.map(item=>item.min)},{name:"Cel mai mare scor",labels:page.map(item=>item.competency),values:page.map(item=>item.max)},{name:"Mediana sau scorul median",labels:page.map(item=>item.competency),values:page.map(item=>item.median)}],{x:1.0,y:1.1,w:8.8,h:5.3,...chartOptions(),showLegend:false,chartColors:[T.range,T.range,T.range],lineSize:0,lineDataSymbol:"circle",lineDataSymbolSize:26});slide.addText(`Benchmark: ${payload.bands.low}–${payload.bands.high}`,{x:10.0,y:1.3,w:2.1,h:.3,fontFace:FONT_BODY,fontSize:10,bold:true,color:T.navy,margin:0});addSources(slide,"Template - raport de grup - RO.pptx · slide 4 (TREND range-chart frame); native chart data from normalized payload");});}
